import{z as l,x as s,o as a,c as p,q as i,j as r,D as n,d as m,s as t,S as o}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"Qwen3-Omni 作为语音理解基座","description":"","frontmatter":{"title":"Qwen3-Omni 作为语音理解基座","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/qwen3-omni-speech-base.md","filePath":"llm/qwen3-omni-speech-base.md","lastUpdated":1791413859000}'),T={name:"llm/qwen3-omni-speech-base.md"};function E(S,e,h,R,B,d){const A=s("Mermaid");return a(),p("div",null,[e[2]||(e[2]=i('<h1 id="qwen3-omni-作为语音理解基座" tabindex="-1">Qwen3-Omni 作为语音理解基座 <a class="header-anchor" href="#qwen3-omni-作为语音理解基座" aria-label="Permalink to &quot;Qwen3-Omni 作为语音理解基座&quot;">​</a></h1><div class="epigraph"><p>Qwen3-ASR 家族模型利用 Qwen3-Omni 作为基础模型，后者已被证明具有强音频理解能力。</p><footer>—— Qwen Team，Qwen3-ASR Technical Report，arXiv:2601.21337</footer></div><p>专用 ASR 可以从随机初始化的编码器–解码器训起。Qwen3-ASR 没有走这条路：它把语音理解的先验放在 Qwen3-Omni 里，再在其上做 ASR 后训练，接上转写格式与语种头。基座负责「听懂」——语种、内容、噪声、非语音、乃至音画场景；ASR 头负责「写成规定格式的字」。Qwen3-Omni 技术报告描述的是全模态 Thinker–Talker MoE，音频编码器从 Whisper 换成自训 AuT，支持最长约 40 分钟的音频理解。Qwen2.5-Omni 已引入 Thinker–Talker 与 TM-RoPE。本篇把 Omni 当作 ASR 的语音理解基座来讲，而不把 30B MoE 的全部生成能力复述成产品页。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若 ASR 只在转写平行语料上训练，监督只有 \\(p(y_{\\mathrm{asr}}\\mid x)\\)，看不见「这是笑声」「这是中英夹杂」「这是歌」。Omni 基座先在更宽的任务上估计 \\(p(u\\mid x)\\)，\\(u\\) 可以是字幕、场景描述或对话回复；ASR 后训练再把 \\(u\\) 的表示收口成转写。遇到这些情况，专用 AED 往往硬吐字或插入噪声词。通用音频理解模型在字幕、音景、语音指令上见过更宽的标签，隐状态对非朗读声学更稳，但解码器太自由，会把转写写成摘要。需要一种继承：理解来自 Omni，输出契约来自 ASR SFT。</p><p>另一个问题是模态互相伤害。早期多模态常「会听就不会写代码」。Qwen3-Omni 声称相对同尺寸 Qwen 单模态模型，文本与视觉不退化，同时在大量音频与音画基准上达到开源或总体 SOTA。只有基座本身没有用音频换掉语言，ASR 后训练才站得住；否则接上转写头时，语言模型已经残了。</p><h3 id="基座与头的分工" tabindex="-1">基座与头的分工 <a class="header-anchor" href="#基座与头的分工" aria-label="Permalink to &quot;基座与头的分工&quot;">​</a></h3><p>基座：AuT 编码器 + Thinker LLM（Omni 预训练，含约 3T token 量级的多任务，见 ASR 报告对 Omni 阶段的转述）提供音频语义空间。头：projector 与 Qwen3 小解码器（0.6B / 1.7B）在 ASR 数据上做格式迁移。发布的 ASR 模型不是 30B-A3B 的 Thinker 原装，而是把理解能力蒸馏、迁移到可部署的稠密 Qwen3 上，并换用单独预训练的 AuT 规格（180M / 300M）。「建在其上」指训练继承与表示继承，不是把 30B 原盘当 ASR 服务。</p><p><span class="marginnote">术语翻译：后训练里的 SFT（监督微调）就是拿成对的「音频–标准转写」让模型练输出格式，不改它已经会的东西。可以类比成：先上完通识大学（Omni 预训练），再进速记培训班（ASR SFT）——培训班教的是格式和手速，不是重新教你认字。</span></p><p><span class="marginnote">Qwen3-Omni 的 Talker、多码本 codec、234 ms 首包延迟属于语音生成。ASR 基座用的是理解侧：AuT + Thinker 表征。不要把 Omni 的会说当成 ASR 的会写。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Qwen3-Omni 用 Thinker–Talker：Thinker 做多模态理解与文本，Talker 做流式语音合成。相对 Qwen2.5-Omni，音频前端从 Whisper 换成约 650M 参数的 AuT，在约 2000 万小时监督音频上从零训练，token 率 12.5 Hz，动态窗口注意力服务流式 prefill。语音理解覆盖 19 种语言，文本 119 种；单实例音频理解可达约 40 分钟。这些数字描述基座的听力覆盖，不是 ASR 产品的 52 语种/方言（后者在 ASR 后训练中扩展到中文方言等）。</p><p>Qwen3-ASR 的训练叙述把 Omni 预训练列为第二阶段，与 AuT 预训练并列，然后才是 ASR SFT 与 RL。两个发布尺寸的 ASR 都「训练了 3T token 的 Omni 阶段」以获得多模态理解，再在不相交的较小多语数据上做转写格式 SFT。上下文偏置、非语音、流式增强数据也在 SFT 出现，说明基座的通用理解被收口，而不是被扔掉。</p>',13)),(a(),r(o,null,{default:n(()=>[t(A,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TB%0A%20%20OMNI%5B%22Qwen3-Omni%20%E7%90%86%E8%A7%A3%E4%BE%A7%20AuT%20%2B%20Thinker%22%5D%20--%3E%20INIT%5B%22%E5%88%9D%E5%A7%8B%E5%8C%96%20ASR%20%E8%AE%AD%E7%BB%83%22%5D%0A%20%20AUT%5B%22%E7%8B%AC%E7%AB%8B%E9%A2%84%E8%AE%AD%E7%BB%83%E7%9A%84%20AuT%22%5D%20--%3E%20ENC%5B%22ASR%20%E9%9F%B3%E9%A2%91%E7%BC%96%E7%A0%81%E5%99%A8%22%5D%0A%20%20INIT%20--%3E%20LLM%5B%22Qwen3-0.6B%20%2F%201.7B%20%E8%A7%A3%E7%A0%81%E5%99%A8%22%5D%0A%20%20ENC%20--%3E%20PROJ%5B%22projector%22%5D%0A%20%20PROJ%20--%3E%20LLM%0A%20%20LLM%20--%3E%20ASR%5B%22%E8%AF%AD%E7%A7%8D%20%2B%20%E8%BD%AC%E5%86%99%22%5D%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[m(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=i('<h3 id="为什么不直接用-omni-当-asr" tabindex="-1">为什么不直接用 Omni 当 ASR <a class="header-anchor" href="#为什么不直接用-omni-当-asr" aria-label="Permalink to &quot;为什么不直接用 Omni 当 ASR&quot;">​</a></h3><p>Omni 会聊天、会推理、会生成语音，延迟与参数对纯转写不划算，且指令跟随与转写稳定性冲突。ASR 报告写明 SFT 的目标是 ASR-only，减轻指令注入。小解码器加专用 AuT，才能在 0.6B 级别做到约 92 ms TTFT 与高并发。基座提供的是预训练权重与数据课程，推理图是瘦身之后的。这与 NLP 里「用大模型当基座、再训分类头」相同，只是头是整个小型 LLM 加音频口。</p><p><span class="marginnote">术语翻译：TTFT（time-to-first-token）是从提交音频到吐出第一个转写字的延迟。92 ms 大约是人眨一次眼（100–400 ms）的三分之一，用户感觉是「刚说完就出字」。数字实例：0.6B 权重按 bfloat16 存约 1.2 GB，只有 30B 级 MoE 的约 1/50，这正是单卡高并发的底气。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Omni 预训练让音频表示与文本空间对齐：同一实体在语音和文字里靠近，专名才能从语言模型抄到转写里。仅 ASR 平行语料很难覆盖足够的实体字符串。方言与噪声上，理解任务（例如嘈杂场景字幕）提供的梯度比干净朗读更接近真实 ASR。Qwen3-Omni 在音频基准上相对闭源系统的比较，是在论证这块表示值得当基座，而不是论证 30B 应上线转写。</p><p>记 Omni 理解侧输出音频 token 序列 \\(H^{\\mathrm{omni}}\\)，ASR 侧经 projector \\(P\\) 得到</p> \\[H^{\\mathrm{asr}}=P\\bigl(\\mathrm{AuT}(x)\\bigr). \\]<p>训练继承要求 \\(H^{\\mathrm{asr}}\\) 落在与文本 LLM 已对齐的邻域内，而不是从随机投影开始。迁移时会发生能力裁剪。Omni 能做的音频问答、思维链，ASR 头不再暴露。评测 ASR 时不应要求它回答「这段话什么态度」；那是基座任务。反过来，Omni 的 ASR 分数与专用 Qwen3-ASR 也不应混表：解码器大小、AuT 规格、是否 RL、是否 52 方言，都不同。基座关系是训练图上的箭头，不是分数可传递性。</p><p><span class="marginnote">Qwen2.5-Omni（arXiv:2503.20215）已证明 Thinker–Talker 与块状音画编码可行，音频编码器仍偏 Whisper 系。Qwen3-Omni（arXiv:2509.17765）用 AuT 替换并加长音频窗口。Qwen3-ASR 继承的是后者这条理解线。</span></p><h3 id="语言覆盖的不对称" tabindex="-1">语言覆盖的不对称 <a class="header-anchor" href="#语言覆盖的不对称" aria-label="Permalink to &quot;语言覆盖的不对称&quot;">​</a></h3>',10)),(a(),r(o,null,{default:n(()=>[t(A,{id:"mermaid-66",class:"mermaid",graph:"flowchart%20LR%0A%20%20O19%5B%22Omni%20%E5%9F%BA%E5%BA%A7%2019%20%E8%AF%AD%E5%90%AC%E5%8A%9B%22%5D%20--%3E%20SFT%5B%22ASR%20SFT%20%E4%BC%AA%E6%A0%87%E6%B3%A8%E6%95%B0%E6%8D%AE%22%5D%0A%20%20SFT%20--%3E%20P30%5B%2230%20%E8%AF%AD%E8%BD%AC%E5%86%99%22%5D%0A%20%20SFT%20--%3E%20D22%5B%2222%20%E7%A7%8D%E4%B8%AD%E6%96%87%E6%96%B9%E8%A8%80%22%5D%0A%20%20P30%20--%3E%20T52%5B%22%E4%BA%A7%E5%93%81%E5%8F%A3%E5%BE%84%2030%2B22%22%5D%0A%20%20D22%20--%3E%20T52%0A%20%20N52%5B%2252%20%E2%89%A0%20Omni%20%E7%BA%B8%E9%9D%A2%2019%22%5D%20-.%E5%8B%BF%E6%B7%B7.-%3E%20T52%0A"})]),fallback:n(()=>[...e[1]||(e[1]=[m(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=i('<p>Omni 语音输入 19 语、ASR 产品 30 语加 22 种中文方言。扩展来自 ASR 阶段数据，不是 Omni 纸面上的 19 自动变成 52。基座提供的是多语语音的一般表征与英语/汉语主干部，方言要靠伪标注与 SFT 补。把「Omni 会 19 语」写成「ASR 只有 19 语」或反过来，都是错的继承。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>用大 Omni 当在线 ASR 会把 MoE 路由、Talker 显存和安全策略一起拖进转写路径，成本错误。用未经 Omni 的随机 Qwen3 接 AuT，会缺少音–文对齐，专名与指令噪声会差一截。中间道路是报告所写：Omni 课程 + 小解码器。</p><p>基座升级与 ASR 发布不同步时，会出现「Omni 新版本听觉更好，ASR 仍是旧投影」的版本漂移。工程上应锁定三件套版本：Omni 预训练检查点、AuT 检查点、ASR SFT 数据。开放权重下，用户微调 ASR 若把学习率开太大，会洗掉基座的理解，退回普通小 AED。</p><p><span class="marginnote">为什么重要：基座的理解是几万亿 token「腌」进权重里的，而 ASR 微调数据相对很小。学习率一开大，少数几步就能把这点理解冲掉——表现是模型转写变差、专名开始乱写，且不可逆（只能回滚检查点重来）。微调小基座模型时，学习率宁小勿大。</span></p><p><span class="marginnote">「语音理解基座」不等于「语音识别冠军基座」。理解基准（音景、指令、音画）与 WER 相关但不相同。选基座要看迁移后的转写，而不是只看 Omni 论文表格。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Qwen3-ASR 的语音理解先验来自 Qwen3-Omni；ASR 头是格式化的小 Qwen3 解码器加 projector，不是 30B Thinker 原装上线。</li><li>Omni 理解侧用自训 AuT 替换 Whisper，提供 12.5 Hz 表示与长音频窗口；Talker 生成侧不进入 ASR 推理。</li><li>后训练把通用理解收口为语种+转写，并扩展方言覆盖。</li><li>基座关系是训练继承，分数与语种表不可在 Omni 与 ASR 之间直接划等号。</li><li>Qwen2.5-Omni 提供 Thinker–Talker 前史；Qwen3-Omni 提供可被 ASR 接住的听觉表示。</li><li>出处：Xu 等，Qwen3-Omni Technical Report，arXiv:2509.17765；Xu 等，Qwen2.5-Omni Technical Report，arXiv:2503.20215；Shi 等，Qwen3-ASR Technical Report，arXiv:2601.21337（2026 年 1 月）。</li></ul>',8))])}const u=l(T,[["render",E]]);export{c as __pageData,u as default};
